function Format-Size([long]$Bytes) {
    if($Bytes -lt 1KB){return "$Bytes B"}; if($Bytes -lt 1MB){return ('{0:N1} KB' -f ($Bytes/1KB))}; if($Bytes -lt 1GB){return ('{0:N1} MB' -f ($Bytes/1MB))}; return ('{0:N2} GB' -f ($Bytes/1GB))
}
function Get-Excluded([string]$Path) {
    $rules=$exclude.Text.Split(';',[StringSplitOptions]::RemoveEmptyEntries) | ForEach-Object {$_.Trim()}
    $parts=$Path.Replace('/','\').Split('\')
    foreach($rule in $rules) { if($rule.StartsWith('*.') -and $Path.EndsWith($rule.Substring(1),[StringComparison]::OrdinalIgnoreCase)){return $true}; if($parts -contains $rule){return $true} }
    return $false
}
function Get-Relative([string]$File) {
    if(-not $preserve.Checked -or -not (Test-Path -LiteralPath $source.Text -PathType Container)){return [IO.Path]::GetFileName($File)}
    $root=[IO.Path]::GetFullPath($source.Text).TrimEnd('\')+'\'; $full=[IO.Path]::GetFullPath($File)
    if($full.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){return $full.Substring($root.Length)}; return [IO.Path]::GetFileName($full)
}
function Refresh-List {
    $list.BeginUpdate(); $list.Items.Clear()
    foreach($item in $script:items){$row=New-Object System.Windows.Forms.ListViewItem($item.Source); [void]$row.SubItems.Add($item.Relative); [void]$row.SubItems.Add((Format-Size $item.Size)); [void]$row.SubItems.Add($item.Status); $row.Tag=$item; $row.Checked=$item.Included; [void]$list.Items.Add($row)}
    $list.EndUpdate(); $chosen=@($script:items | Where-Object {$_.Included}); $total=($chosen | Measure-Object -Property Size -Sum).Sum; $sqlCount=@($chosen | Where-Object {[IO.Path]::GetExtension($_.Relative).Equals('.sql',[StringComparison]::OrdinalIgnoreCase)}).Count; $conflicts=$null; if(-not [string]::IsNullOrWhiteSpace($destination.Text) -and (Test-Path -LiteralPath $destination.Text -PathType Container)){$conflicts=@($chosen | Where-Object {Test-Path -LiteralPath (Join-Path $destination.Text $_.Relative)}).Count}; $summary.Text=('{0:N0}/{1:N0} file da tich  {2}' -f $chosen.Count,$script:items.Count,(Format-Size $total)) + $(if($null -eq $conflicts){'  chon Dich de kiem tra trung'}elseif($conflicts){'  '+$conflicts+' file dich da ton tai'}else{'  chua co trung file'}); if($script:dashboardTotal){$script:dashboardTotal.Text=('{0:N0}' -f $script:items.Count);$script:dashboardChosen.Text=('{0:N0}' -f $chosen.Count);$script:dashboardSql.Text=('{0:N0}' -f $sqlCount);$script:dashboardSize.Text=(Format-Size $total);$script:dashboardNote.Text=$(if($null -eq $conflicts){'Chon thu muc dich de kiem tra file trung.'}elseif($conflicts){'Co '+$conflicts+' file trung o thu muc dich.'}else{'Khong co file trung o thu muc dich.'})}
}
function Add-DeliveryPaths([string[]]$Paths, [hashtable]$GitStatus=@{}) {
    foreach($input in $Paths) {
        $files=@(); if(Test-Path -LiteralPath $input -PathType Leaf){$files=@(Get-Item -LiteralPath $input)} elseif(Test-Path -LiteralPath $input -PathType Container){$files=Get-ChildItem -LiteralPath $input -File -Recurse -Force -ErrorAction SilentlyContinue}
        foreach($file in $files){if((Get-Excluded $file.FullName) -or @($script:items | Where-Object {$_.Source -eq $file.FullName}).Count){continue}; $state=if($GitStatus.ContainsKey($file.FullName)){'Git '+$GitStatus[$file.FullName]}else{'San sang'}; [void]$script:items.Add([pscustomobject]@{Source=$file.FullName;Relative=(Get-Relative $file.FullName);Size=$file.Length;Status=$state;Included=$true})}
    }; Refresh-List
}
function Get-GitRoot {
    $candidate=$source.Text.Trim(); if(-not $candidate){throw 'Hay chon thu muc Nguon.'}
    while($candidate -and -not (Test-Path -LiteralPath $candidate -PathType Container)){$parent=Split-Path -Path $candidate -Parent;if($parent -eq $candidate){break};$candidate=$parent}
    if(-not $candidate -or -not (Test-Path -LiteralPath $candidate -PathType Container)){throw 'Khong tim thay thu muc Nguon.'}
    $gitRootOutput=@(& git -c ("safe.directory="+$candidate) -C $candidate rev-parse --show-toplevel 2>$null); $gitExit=$LASTEXITCODE; $root=($gitRootOutput | Select-Object -First 1)
    if($gitExit -ne 0 -or [string]::IsNullOrWhiteSpace($root)){
        $repos=@(Get-ChildItem -LiteralPath $candidate -Directory -Force -ErrorAction SilentlyContinue | Where-Object {Test-Path -LiteralPath (Join-Path $_.FullName '.git') -PathType Container})
        if($repos.Count -eq 1){$root=$repos[0].FullName}else{throw 'Nguon chua tro dung Git repository. Chon thu muc chua .git (vi du ...\Gom9\flexDB).'}
    }
    $root=$root.Trim().Replace('/','\'); $source.Text=$root; return $root
}
function Invoke-Git([string]$Root, [string[]]$Arguments) { & git -c ("safe.directory="+$Root) -C $Root @Arguments }
function Load-Branches {
    try {$root=Get-GitRoot; $branches=@(Invoke-Git $root @('branch','--all','--no-color','--format=%(refname:short)') | Where-Object {$_}); foreach($box in @($branchOne,$branchTwo)){$box.Items.Clear(); [void]$box.Items.AddRange([object[]]$branches)}; $current=(Invoke-Git $root @('branch','--show-current')).Trim(); if(-not $branchOne.Text){$branchOne.Text=if($branches -contains 'main'){'main'}elseif($branches -contains 'master'){'master'}else{$current}};if(-not $branchTwo.Text){$branchTwo.Text=$current}; $gitInfo.Text='Da tai '+$branches.Count+' nhanh.'} catch {$gitInfo.Text='Git: '+$_.Exception.Message}
}
function Add-GitLines([hashtable]$Map,[string[]]$Lines,[string]$Root) {
    foreach($line in $Lines){if([string]::IsNullOrWhiteSpace($line)){continue}; $p=$line -split "`t"; if($p.Count -lt 2){continue}; $state=$p[0].Trim(); if([string]::IsNullOrWhiteSpace($state)){continue}; if($state.StartsWith('R') -or $state.StartsWith('C')){$path=$p[$p.Count-1]}else{$path=$p[1]}; if(-not [string]::IsNullOrWhiteSpace($path) -and -not [string]::IsNullOrWhiteSpace($Root)){$Map[[IO.Path]::GetFullPath((Join-Path -Path $Root -ChildPath $path.Trim()))]=$state}}
}
function Import-GitDiff {
    try {
        $root=Get-GitRoot; if(-not $branchOne.Text -or -not $branchTwo.Text){Load-Branches}; if(-not $branchOne.Text -or -not $branchTwo.Text){throw 'Hay nhap/chon du Nhanh 1 va Nhanh 2.'}; $source.Text=$root; $map=@{}
        Add-GitLines $map @(Invoke-Git $root @('diff','--name-status','-M','--diff-filter=ACMR',($branchOne.Text.Trim()+'...'+$branchTwo.Text.Trim()))) $root
        if($working.Checked){Add-GitLines $map @(Invoke-Git $root @('diff','--name-status','-M','HEAD')) $root; Add-GitLines $map @(Invoke-Git $root @('diff','--name-status','-M','--cached')) $root; foreach($path in @(Invoke-Git $root @('ls-files','--others','--exclude-standard'))){if(-not [string]::IsNullOrWhiteSpace($path)){$map[[IO.Path]::GetFullPath((Join-Path -Path $root -ChildPath $path.Trim()))]='A'}}}
        $before=$script:items.Count; $files=@($map.Keys | Where-Object {$_ -and -not [string]::IsNullOrWhiteSpace([string]$_) -and (Test-Path -LiteralPath $_ -PathType Leaf)}); Add-DeliveryPaths $files $map; $gitInfo.Text=('{0} thay doi tu {1}...{2}; them {3} file. Rename chi dung ten moi.' -f $map.Count,$branchOne.Text,$branchTwo.Text,($script:items.Count-$before))
    } catch {$gitInfo.Text='Git diff loi: '+$_.Exception.Message; if($env:FSSCOPY_TEST -eq '1'){throw}; [Windows.Forms.MessageBox]::Show($_.Exception.Message,'Git diff loi',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Error)}
}
