function Import-PastedList([string]$Text) {
    $paths=@(); foreach($line in ($Text -split "`r?`n")) { $value=$line.Trim().Trim('"'); if(-not $value){continue}; if($value.Contains("`t")){$value=@($value -split "`t" | Where-Object {-not [string]::IsNullOrWhiteSpace($_)} | Select-Object -Last 1).Trim()}; if(-not $value){continue}; if(-not [IO.Path]::IsPathRooted($value)){if([string]::IsNullOrWhiteSpace($source.Text)){[Windows.Forms.MessageBox]::Show('Danh sach dang dung path relative. Hay chon Thu muc nguon truoc, hoac dan path tuyet doi.','Thieu thu muc nguon',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Information);return};$value=Join-Path -Path $source.Text -ChildPath $value}; $paths+=$value }
    Add-DeliveryPaths $paths
}
