function Next-Name([string]$Path) {$dir=Split-Path $Path; $base=[IO.Path]::GetFileNameWithoutExtension($Path); $ext=[IO.Path]::GetExtension($Path); for($i=1;;$i++){$candidate=Join-Path $dir ($base+' ('+$i+')'+$ext); if(-not(Test-Path -LiteralPath $candidate)){return $candidate}}}
function Get-Hash([string]$Path) {return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash}
function Copy-Delivery {
    $toCopy=@($script:items | Where-Object {$_.Included}); if(-not $toCopy.Count){[Windows.Forms.MessageBox]::Show('Hay tich it nhat mot file trong danh sach.');return}; if(-not $destination.Text){[Windows.Forms.MessageBox]::Show('Hay chon thu muc Dich.');return}; New-Item -ItemType Directory -Path $destination.Text -Force | Out-Null; $copy.Enabled=$false; $progress.Maximum=$toCopy.Count; $progress.Value=0; $manifest=@()
    try {for($i=0;$i -lt $toCopy.Count;$i++){ $item=$toCopy[$i]; $target=Join-Path $destination.Text $item.Relative; New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null; if(Test-Path -LiteralPath $target){if($conflict.SelectedIndex -eq 0){$item.Status='Bo qua (trung)';$manifest+=New-Object psobject -Property @{Source=$item.Source;Destination=$target;Bytes=$item.Size;Result='Skipped';Detail='File exists'};$progress.Value=$i+1;continue};if($conflict.SelectedIndex -eq 2){$target=Next-Name $target}}; $status.Text=('Dang copy {0}/{1}: {2}' -f ($i+1),$toCopy.Count,[IO.Path]::GetFileName($item.Source)); [Windows.Forms.Application]::DoEvents(); [IO.File]::Copy($item.Source,$target,$true); [IO.File]::SetLastWriteTimeUtc($target,[IO.File]::GetLastWriteTimeUtc($item.Source)); if($verify.Checked -and (Get-Hash $item.Source) -ne (Get-Hash $target)){throw 'SHA-256 khong khop: '+$item.Source}; $item.Relative=$target.Substring($destination.Text.TrimEnd('\').Length).TrimStart('\');$item.Status=if($verify.Checked){'Da copy + xac minh'}else{'Da copy'};$manifest+=New-Object psobject -Property @{Source=$item.Source;Destination=$target;Bytes=$item.Size;Result='Copied';Detail=$item.Status};$progress.Value=$i+1;Refresh-List }
        $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'; $manifestPath=Join-Path $destination.Text ('FSSCopy_manifest_'+$stamp+'.csv');$manifest | Select-Object Source,Destination,Bytes,Result,Detail | Export-Csv -LiteralPath $manifestPath -NoTypeInformation -Encoding UTF8
        if($runscript.Checked){$sql=@($toCopy | Where-Object {[IO.Path]::GetExtension($_.Relative).Equals('.sql',[StringComparison]::OrdinalIgnoreCase) -and $_.Status -match 'Da copy|Bo qua'} | ForEach-Object {'@@'+$_.Relative.Replace('\','/')} | Sort-Object -Unique);if($sql.Count){if(-not $dbUser.Text -or -not $dbPassword.Text -or -not $dbTns.Text){throw 'Hay bam Cau hinh SQLPlus va dien DB User, Password, TNS truoc khi tao runscript.'};$logPath=if($dbLog.Text){$dbLog.Text}else{'../log/install.log'};@('SET TRUNC OFF','SET HEADING ON','SET DEFINE OFF','',('CONNECT '+$dbUser.Text+'/'+$dbPassword.Text+'@'+$dbTns.Text),('SPO '+$logPath+';'),'')+$sql+@('','SPO OFF;','exit') | Set-Content -LiteralPath (Join-Path $destination.Text 'runscript.sql') -Encoding UTF8}}
        $status.Text='Hoan tat. Manifest: '+[IO.Path]::GetFileName($manifestPath);if($env:FSSCOPY_TEST -ne '1'){[Windows.Forms.MessageBox]::Show('Copy hoan tat.','FSS Copy Portable')}
    } catch {[Windows.Forms.MessageBox]::Show($_.Exception.Message,'FSS Copy Portable');$status.Text='Co loi: '+$_.Exception.Message} finally {$copy.Enabled=$true;Refresh-List}
}

